Leading call fires at once; trailing call catches the final scroll position.

```js
function throttle(fn, wait) {
  let last = 0;
  let timer = null;
  return function (...args) {
    const remaining = wait - (Date.now() - last);
    if (remaining <= 0) {
      clearTimeout(timer);
      timer = null;
      last = Date.now();
      fn.apply(this, args);
    } else if (!timer) {
      timer = setTimeout(() => {
        last = Date.now();
        timer = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}

function onScroll() {
  console.log(window.scrollY);
}

window.addEventListener('scroll', throttle(onScroll, 200), { passive: true });
```

`passive: true` keeps scrolling smooth; drop it if the handler calls `preventDefault()`.

